-- Stonefellow canonical Profile Agent / proactive attention schema.
-- Normal deployments should use /upgrade.php. This file is a reference/manual fallback.
CREATE TABLE IF NOT EXISTS user_profiles (user_id INT UNSIGNED NOT NULL PRIMARY KEY,username VARCHAR(80) NULL,bio TEXT NULL,cover_path VARCHAR(500) NOT NULL DEFAULT '',website_url VARCHAR(500) NOT NULL DEFAULT '',instagram_url VARCHAR(500) NOT NULL DEFAULT '',tiktok_url VARCHAR(500) NOT NULL DEFAULT '',youtube_url VARCHAR(500) NOT NULL DEFAULT '',spotify_url VARCHAR(500) NOT NULL DEFAULT '',apple_music_url VARCHAR(500) NOT NULL DEFAULT '',is_public TINYINT(1) NOT NULL DEFAULT 0,share_visit_identity TINYINT(1) NOT NULL DEFAULT 0,profile_agent_id BIGINT UNSIGNED NULL,profile_agent_enabled TINYINT(1) NOT NULL DEFAULT 0,profile_agent_greeting VARCHAR(500) NOT NULL DEFAULT '',profile_agent_instructions TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_user_profiles_username(username),INDEX idx_user_profiles_public(is_public,username,user_id),INDEX idx_user_profiles_agent(profile_agent_id,profile_agent_enabled),CONSTRAINT fk_user_profiles_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_user_profiles_agent FOREIGN KEY(profile_agent_id) REFERENCES user_agents(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS profile_visit_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id INT UNSIGNED NOT NULL,visitor_user_id INT UNSIGNED NULL,session_key CHAR(64) NOT NULL,identity_disclosed TINYINT(1) NOT NULL DEFAULT 0,view_count INT UNSIGNED NOT NULL DEFAULT 0,first_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_message_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_profile_visit_session(owner_user_id,session_key),INDEX idx_profile_visit_owner(owner_user_id,last_seen_at,id),INDEX idx_profile_visit_visitor(visitor_user_id,last_seen_at),CONSTRAINT fk_profile_visit_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_profile_visit_visitor FOREIGN KEY(visitor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS profile_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id INT UNSIGNED NOT NULL,profile_session_id BIGINT UNSIGNED NULL,visitor_user_id INT UNSIGNED NULL,profile_agent_id BIGINT UNSIGNED NULL,event_type VARCHAR(50) NOT NULL,priority SMALLINT UNSIGNED NOT NULL DEFAULT 10,dedupe_key CHAR(64) NULL,metadata_json LONGTEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_profile_event_dedupe(dedupe_key),INDEX idx_profile_event_owner(owner_user_id,created_at,id),CONSTRAINT fk_profile_event_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_profile_event_session FOREIGN KEY(profile_session_id) REFERENCES profile_visit_sessions(id) ON DELETE SET NULL,CONSTRAINT fk_profile_event_visitor FOREIGN KEY(visitor_user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_profile_event_agent FOREIGN KEY(profile_agent_id) REFERENCES user_agents(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS profile_agent_conversations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id INT UNSIGNED NOT NULL,profile_agent_id BIGINT UNSIGNED NOT NULL,profile_session_id BIGINT UNSIGNED NOT NULL,visitor_user_id INT UNSIGNED NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',last_summary VARCHAR(1000) NOT NULL DEFAULT '',started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_message_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_profile_conversation_owner(owner_user_id,status,last_message_at,id),CONSTRAINT fk_profile_conversation_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_profile_conversation_agent FOREIGN KEY(profile_agent_id) REFERENCES user_agents(id) ON DELETE CASCADE,CONSTRAINT fk_profile_conversation_session FOREIGN KEY(profile_session_id) REFERENCES profile_visit_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_profile_conversation_visitor FOREIGN KEY(visitor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS profile_agent_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,conversation_id BIGINT UNSIGNED NOT NULL,sender_type VARCHAR(20) NOT NULL,sender_user_id INT UNSIGNED NULL,message TEXT NOT NULL,context_json LONGTEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_profile_messages_conversation(conversation_id,id),CONSTRAINT fk_profile_message_conversation FOREIGN KEY(conversation_id) REFERENCES profile_agent_conversations(id) ON DELETE CASCADE,CONSTRAINT fk_profile_message_user FOREIGN KEY(sender_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS agent_attention_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id INT UNSIGNED NOT NULL,source_event_id BIGINT UNSIGNED NULL,source_conversation_id BIGINT UNSIGNED NULL,profile_agent_id BIGINT UNSIGNED NULL,visitor_user_id INT UNSIGNED NULL,attention_type VARCHAR(50) NOT NULL,priority SMALLINT UNSIGNED NOT NULL DEFAULT 10,status VARCHAR(20) NOT NULL DEFAULT 'pending',headline VARCHAR(255) NOT NULL,summary TEXT NOT NULL,assessment VARCHAR(1000) NOT NULL DEFAULT '',recommended_response VARCHAR(1000) NOT NULL DEFAULT '',actions_json LONGTEXT NULL,context_json LONGTEXT NULL,snoozed_until DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_attention_event(source_event_id),INDEX idx_attention_owner(owner_user_id,status,priority,created_at,id),CONSTRAINT fk_attention_owner FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_attention_event FOREIGN KEY(source_event_id) REFERENCES profile_events(id) ON DELETE CASCADE,CONSTRAINT fk_attention_conversation FOREIGN KEY(source_conversation_id) REFERENCES profile_agent_conversations(id) ON DELETE CASCADE,CONSTRAINT fk_attention_agent FOREIGN KEY(profile_agent_id) REFERENCES user_agents(id) ON DELETE SET NULL,CONSTRAINT fk_attention_visitor FOREIGN KEY(visitor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
